'use strict';
(() => {
const D=window.FESTIVAL_DATA,$=s=>document.querySelector(s),main=$('main');
const pages=['index.html','program.html','performers.html','venues.html','info.html','search.html','tickets.html','cart.html','account.html','news.html'];
const pageTitles={'index.html':'Festival','program.html':'Program 2027','performers.html':'Účinkující','venues.html':'Festivalové scény','info.html':'Praktické informace','search.html':'Vyhledávání','tickets.html':'Vstupenky','cart.html':'Košík','account.html':'Můj účet','news.html':'Novinky'};
const diskMode=location.protocol==='file:';
const pathnamePage=location.pathname.split('/').pop()||'index.html';
const page=diskMode&&pages.includes(new URLSearchParams(location.search).get('page'))?new URLSearchParams(location.search).get('page'):pathnamePage;
document.title=(pageTitles[page]||'Festival')+' | Prague Pulse Fest';
if(diskMode){
const descriptions={'index.html':'Prague Pulse Fest: 1.–3. srpna 2027 ve Vltava Parku v Praze. Program, účinkující a vstupenky.','program.html':'Program 60 vystoupení. Filtrujte podle dne, scény a ukládejte oblíbené koncerty.','performers.html':'Všech 60 účinkujících Prague Pulse Fest, jejich profily a koncerty.','venues.html':'Main Hall, River Stage a Club Stage ve Vltava Parku v Praze.','info.html':'Praktické informace: doprava, přístupnost, vstupenky a časté dotazy.','search.html':'Hledání v programu, interpretech, scénách a informacích Prague Pulse Fest.','tickets.html':'Interaktivní výběr VIP, Regular a stání. Školní ukázka vstupenek v PDF.','cart.html':'Souhrn vstupenek a objednávka s lokálním účtem i bez registrace.','account.html':'Lokální přihlášení, registrace a historie školních objednávek.','news.html':'Novinky a aktuální informace Prague Pulse Fest 2027.'};
$('meta[name="description"]').content=descriptions[page]||descriptions['index.html'];
$('meta[property="og:description"]').content=$('meta[name="description"]').content;
}
$('meta[property="og:title"]').content=document.title;
// Keep one file URL for all views: file:// localStorage isolation otherwise differs by browser.
function routeUrl(href){
if(!diskMode||typeof href!=='string'||href.startsWith('#'))return href;
const target=new URL(href,location.href),filename=target.pathname.split('/').pop();
if(!pages.includes(filename))return href;
if(filename==='index.html'&&target.searchParams.has('page'))return target.href;
target.pathname=target.pathname.replace(/[^/]+$/,'index.html');target.searchParams.set('page',filename);return target.href;
}
if(diskMode&&pathnamePage!=='index.html'){location.replace(routeUrl(location.href));return;}
document.addEventListener('click',e=>{const anchor=e.target.closest('a[href]');if(!diskMode||!anchor||anchor.target||anchor.download||e.ctrlKey||e.metaKey||e.shiftKey||e.altKey||e.button!==0)return;const href=anchor.getAttribute('href');const routed=routeUrl(href);if(routed!==href){e.preventDefault();location.href=routed;}});

const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const localizedSearch=v=>{const visit=x=>typeof x==='string'?(window.PulseI18n?.t(x)||x):Array.isArray(x)?x.map(visit):x&&typeof x==='object'?Object.fromEntries(Object.entries(x).map(([k,val])=>[k,visit(val)])):x;return JSON.stringify(v)+' '+JSON.stringify(visit(v));};
const normalize=v=>String(v??'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLocaleLowerCase('cs');
const locale=window.PulseI18n?.lang==='en'?'en-GB':'cs-CZ';
const tr=(cs,en)=>locale==='en-GB'?en:cs;
const money=v=>new Intl.NumberFormat(locale,{style:'currency',currency:'CZK',maximumFractionDigits:0}).format(v);
const date=v=>new Intl.DateTimeFormat(locale,{day:'numeric',month:'long'}).format(new Date(v+'T12:00:00'));
const storage={get(k,fallback=[]){
try{
const value=JSON.parse(localStorage.getItem('pulse:'+k));
if(!Array.isArray(value))return fallback;
if(k==='users')return value.filter(u=>u&&['id','name','email','salt','hash'].every(field=>typeof u[field]==='string')&&/^[a-f0-9]{32}$/.test(u.salt)&&/^[a-f0-9]{64}$/.test(u.hash));
if(k==='orders')return value.filter(o=>o&&typeof o.id==='string'&&Array.isArray(o.tickets)&&o.tickets.every(validTicket));
if(k==='favorites')return value.filter(id=>typeof id==='string'&&D.events.some(e=>e.id===id));
return value;
}catch{return fallback;}
},set(k,v){localStorage.setItem('pulse:'+k,JSON.stringify(v));}};
let session;try{session=JSON.parse(localStorage.getItem('pulse:auth')||'null');if(!session||!Number.isFinite(session.expires)||session.expires<=Date.now()){localStorage.removeItem('pulse:auth');session=null;}}catch{session=null;}
function rememberLogin(id){const auth={id,expires:Date.now()+7*24*60*60*1000};localStorage.setItem('pulse:auth',JSON.stringify(auth));sessionStorage.setItem('pulse:session',JSON.stringify({id}));}

let user=storage.get('users').find(u=>u.id===session?.id)||null;
const ticketTypes=[{id:'vip',label:'VIP',price:D.festival.tickets.find(t=>t.id==='t5').price,festivalPrice:D.festival.tickets.find(t=>t.id==='t2').price,sourceId:'t2'},{id:'regular',label:'Regular',price:D.festival.tickets.find(t=>t.id==='t4').price,festivalPrice:D.festival.tickets.find(t=>t.id==='t1').price,sourceId:'t1'},{id:'standing',label:'Stání',price:D.festival.tickets.find(t=>t.id==='t6').price,festivalPrice:D.festival.tickets.find(t=>t.id==='t3').price,sourceId:'t3'}];
const cartKey=()=> 'cart:'+(user?.id||'guest');
const getCart=()=>storage.get(cartKey()).filter(validTicket);
const selected=new Set();
let toastTimer;
function toast(t){$('#status').textContent=t;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#status').textContent='',4500);}
function save(k,v){try{storage.set(k,v);return true;}catch{toast('Prohlížeč nepovolil uložení. Povolte místní úložiště a zkuste to znovu.');return false;}}
function keyId(){return crypto.randomUUID?crypto.randomUUID():Date.now().toString(36)+'-'+Math.random().toString(36).slice(2);}
const link=(href,text,cls='')=>`<a class="${cls}" href="${href}">${text}</a>`;
const crumb=t=>`<div class="crumb"><a href="index.html">Festival</a> <span aria-hidden="true">/</span> ${esc(t)}</div>`;
const heading=(tag,title,desc='')=>`<p class="eyebrow">${tag}</p><h1>${title}</h1>${desc?`<p class="lead">${desc}</p>`:''}`;
function shell(){
const lang=window.PulseI18n?.lang||'cs';
$('#header').innerHTML=window.PulseShell.header({page,user,cartCount:getCart().length,lang,diskMode});
$('#footer').innerHTML=window.PulseShell.footer({lang});
if(diskMode){$('.global-search').action='index.html';$('.global-search').insertAdjacentHTML('beforeend','<input type="hidden" name="page" value="search.html">');}
$('.menu-toggle').onclick=e=>{const open=e.currentTarget.getAttribute('aria-expanded')!=='true';e.currentTarget.setAttribute('aria-expanded',open);$('#navigation').classList.toggle('open',open);};
main.ownerDocument.querySelectorAll('[data-lang]').forEach(button=>button.onclick=()=>window.PulseI18n.setLanguage(button.dataset.lang));
}
function updateCount(){const badge=$('nav a[href="cart.html"] .cart-count');if(badge)badge.textContent=String(getCart().length);}
function openDialog(html){$('#detail-content').innerHTML=html;$('#detail').showModal();}
$('#detail .close').onclick=()=>$('#detail').close();
$('#detail').addEventListener('click',e=>{if(e.target===$('#detail')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
function artistCard(p,i=0){return `<article class="card"><div class="artist-art performer-portrait" style="${esc(window.PerformerArt?.style(p.id)||'')}" aria-hidden="true"><span class="artist-initials">${esc(p.name.split(' ').map(x=>x[0]).join(''))}</span></div><span class="badge">${esc(p.genre)} · ${esc(p.performerType)}</span><h3>${esc(p.name)}</h3><p class="muted">${esc(p.description)}</p><button class="text-button" data-artist="${p.id}">Poznat interpreta <span aria-hidden="true">→</span></button></article>`;}
function eventRows(events){const fav=storage.get('favorites');return events.length?events.map(e=>`<article class="event" data-start="${e.date}T${e.startTime}"><div class="time"><time datetime="${e.date}T${e.startTime}">${date(e.date)}<br>${e.startTime.slice(0,5)}–${e.endTime.slice(0,5)}</time></div><div><span class="badge">${esc(e.venueName)}</span><h3>${esc(e.theme)}</h3><p>${e.performerIds.map(id=>{const p=D.performers.find(x=>x.id===id);return `<button class="text-button small" data-artist="${id}">${esc(p?.name||id)}</button>`;}).join(' · ')}</p><p class="muted">${esc(e.name)}</p></div><div class="event-actions"><button class="secondary small" data-fav="${e.id}" aria-pressed="${fav.includes(e.id)}" aria-label="${fav.includes(e.id)?'Odebrat z':'Přidat do'} oblíbených: ${esc(e.name)}">${fav.includes(e.id)?'♥ Uloženo':'♡ Uložit'}</button><button class="small secondary" data-event="${e.id}">Detail</button></div></article>`).join(''):'<div class="empty">Žádná vystoupení. Zkuste změnit filtry.</div>';}
function artistDetail(id){const p=D.performers.find(x=>x.id===id);if(!p)return;openDialog(`<div class="detail-portrait performer-portrait" style="${esc(window.PerformerArt?.style(p.id)||'')}" aria-hidden="true"></div><p class="eyebrow">Účinkující · ${esc(p.genre)}</p><h2 id="dialog-title">${esc(p.name)}</h2><p>${esc(p.description)}</p><span class="badge">${esc(p.performerType)}</span><h3>Kdy hraje?</h3>${D.events.filter(e=>e.performerIds.includes(id)).map(e=>`<p><time datetime="${e.date}">${date(e.date)}</time> · ${e.startTime.slice(0,5)} · ${esc(e.venueName)}<br><a href="program.html?event=${e.id}">${esc(e.theme)}</a></p>`).join('')||'<p>V programu zatím není vystoupení.</p>'}${link('tickets.html','Vybrat vstupenky →','button')}`);}
function eventDetail(id){const e=D.events.find(x=>x.id===id);if(!e)return;openDialog(`<p class="eyebrow">${esc(e.name)}</p><h2 id="dialog-title">${esc(e.theme)}</h2><p><time datetime="${e.date}">${date(e.date)}</time> · ${e.startTime.slice(0,5)}–${e.endTime.slice(0,5)}</p><p>${esc(e.description)}</p><p>Scéna: ${link('venues.html#'+e.venueId,esc(e.venueName))}</p><p>${e.performers.map(esc).join(' · ')}</p>${link('tickets.html?day='+e.dayId,'Vstupenky na tento den →','button')}`);}
function home(){
main.innerHTML=window.PulseDesign.home(D);
const structured=document.createElement('script');structured.type='application/ld+json';structured.textContent=JSON.stringify({'@context':'https://schema.org','@type':'Festival',name:D.festival.name,startDate:'2027-08-01',endDate:'2027-08-03',description:D.festival.description,location:{'@type':'Place',name:'Vltava Park',address:{'@type':'PostalAddress',streetAddress:'Výstaviště 67',addressLocality:'Praha',postalCode:'170 00',addressCountry:'CZ'}}});main.append(structured);
}
function program(){const params=new URLSearchParams(location.search);main.innerHTML=crumb('Program')+heading('1.–3. srpna / tři scény','Program 2027','Tři dny, tři scény a spousta důvodů zůstat ještě na jeden koncert.')+`<form class="filters" id="program-filters"><div class="field"><label for="day">Den</label><select id="day"><option value="">Všechny dny</option>${D.festival.dates.map(d=>`<option value="${d.id}">${date(d.date)}</option>`).join('')}</select></div><div class="field"><label for="venue">Scéna</label><select id="venue"><option value="">Všechny scény</option>${D.venues.map(v=>`<option value="${v.id}">${esc(v.name)}</option>`).join('')}</select></div><div class="field"><label for="program-q">Interpret nebo téma</label><input id="program-q" type="search" maxlength="120" placeholder="Např. David nebo jazz"></div><label class="check"><input type="checkbox" id="only-favorites">Jen můj program</label><button class="secondary small" type="reset">Zrušit filtry</button></form><p id="result-count" class="count" role="status"></p><h2 class="visually-hidden">Vystoupení</h2><section id="events" aria-label="Vystoupení"></section>`;$('#day').value=params.get('day')||'';$('#venue').value=params.get('venue')||'';
function render(){const q=normalize($('#program-q').value.trim()),fav=storage.get('favorites');const list=D.events.filter(e=>(!$('#day').value||e.dayId===$('#day').value)&&(!$('#venue').value||e.venueId===$('#venue').value)&&(!q||normalize(localizedSearch(e)).includes(q))&&(!$('#only-favorites').checked||fav.includes(e.id))).sort((a,b)=>(a.date+a.startTime).localeCompare(b.date+b.startTime)||a.venueName.localeCompare(b.venueName,locale)||a.id.localeCompare(b.id));$('#result-count').textContent=`${list.length} z ${D.events.length} vystoupení`;$('#events').innerHTML=list.length?D.festival.dates.map(day=>{const events=list.filter(e=>e.dayId===day.id);return events.length?`<section class="program-day" aria-labelledby="program-${day.id}"><div class="program-day-heading"><h2 id="program-${day.id}"><time datetime="${day.date}">${date(day.date)} 2027</time></h2><p class="program-order-note">${tr('Od prvního vystoupení po poslední. Časy jsou uvedené v pražském čase.','From the first performance to the last. All times are Prague local time.')}</p></div>${eventRows(events)}</section>`:'';}).join(''):eventRows([]);}
$('#program-filters').oninput=render;$('#program-filters').onsubmit=e=>e.preventDefault();$('#program-filters').onreset=()=>setTimeout(render,0);main.addEventListener('favorites-changed',render);render();if(params.get('event'))eventDetail(params.get('event'));}
function performers(){main.innerHTML=crumb('Účinkující')+heading('Line-up / 2027','Účinkující','Od kytarových riffů po elektronické beaty. Najdi zvuk, který tě vezme s sebou.')+`<form class="filters" id="artist-filters"><div class="field"><label for="artist-q">Hledat interpreta</label><input id="artist-q" type="search" maxlength="120" placeholder="Název nebo popis…"></div><div class="field"><label for="genre">Žánr</label><select id="genre"><option value="">Všechny žánry</option>${[...new Set(D.performers.map(p=>p.genre))].map(g=>`<option value="${esc(g)}">${esc(g)}</option>`).join('')}</select></div></form><p id="result-count" class="count" role="status"></p><h2 class="visually-hidden">Seznam účinkujících</h2><section id="artists" class="grid three" aria-label="Seznam účinkujících"></section>`;function render(){const q=normalize($('#artist-q').value.trim()),list=D.performers.filter(p=>(!q||normalize(localizedSearch(p)).includes(q))&&(!$('#genre').value||p.genre===$('#genre').value));$('#result-count').textContent=`${list.length} účinkujících`;$('#artists').innerHTML=list.map(artistCard).join('')||'<p class="empty">Žádní účinkující neodpovídají hledání.</p>';}
$('#artist-filters').oninput=render;$('#artist-filters').onsubmit=e=>e.preventDefault();render();const id=new URLSearchParams(location.search).get('id');if(id)artistDetail(id);}
function venues(){main.innerHTML=crumb('Scény')+heading('Vltava Park / Praha','Tři festivalové scény','Od velkých koncertů po komorní sety. Všechny scény najdeš v areálu Vltava Park.')+`<section class="grid three">${D.venues.map((v,i)=>`<article class="card" id="${v.id}"><div class="number">0${i+1} →</div><h2>${esc(v.name)}</h2><p>${esc(v.description)}</p><p class="muted">${esc(v.location)}<br>Kapacita ${v.capacity.toLocaleString(locale)} návštěvníků</p>${link('program.html?venue='+v.id,'Objevit program scény','text-button')}</article>`).join('')}</section>`;}
const infoItems=[
['Kde se festival koná?','Vltava Park, modelový festivalový areál na Výstavišti Praha. Adresa pro navigaci: Výstaviště 67, 170 00 Praha 7.'],
['Jak se dostanu do areálu?','Doporučujeme tramvaj na zastávku Výstaviště nebo metro C na Nádraží Holešovice a navazující tramvaj. Aktuální spojení si před cestou ověř u dopravce.'],
['Co obsahuje VIP?','VIP zahrnuje místo v předních řadách, rychlejší odbavení a odpočinkovou zónu. Třídenní VIP balíček v modelové nabídce zahrnuje také jedno parkovací místo.'],
['Mohu koupit vstupenku bez registrace?','Ano. V košíku stačí zadat jméno a e-mail. Po dokončení objednávky si stáhneš všechny vstupenky v jednom PDF.'],
['Jak dlouho platí třídenní balíček?','Třídenní balíček platí od 1. do 3. srpna 2027 na všechny scény. Stejné sedadlo nebo místo ke stání je vyhrazené po všechny tři dny.'],
['Je areál bezbariérový?','Návrh areálu počítá s bezbariérovými trasami a přístupnými toaletami. Doprovod a individuální potřeby řeší informační bod u hlavního vstupu.']
];
function photoCreditsHtml(){
const lang=window.PulseI18n?.lang==='en'?'en':'cs',t=(cs,en)=>lang==='en'?en:cs,credits=window.PulsePhotoCredits;
const linkTo=(url,label)=>/^https:\/\//.test(String(url||''))?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)}</a>`:esc(label);
const credit=item=>`${esc(item.author||'')} · ${linkTo(item.licenseUrl,item.license||'')} · ${linkTo(item.source,t('Zdroj fotografie','Photo source'))}${item.date?' · '+esc(item.date):''}`;
const photographers=credits?.performers||[];
return `<section id="credits"><h2>${t('Vizuály','Artwork')}</h2><p>${t('Fotografie a původní ilustrace jsou přibalené k webu. Níže najdeš jejich zdroje a licence.','Photographs and original illustrations are bundled with this website. Their sources and licences are listed below.')}</p>${credits?.venue?`<h3>${t('Průmyslový palác / Výstaviště Praha','Industrial Palace / Výstaviště Prague')}</h3><p data-no-translate>${credit(credits.venue)}</p>`:''}${photographers.length?`<details><summary>${t('Fotografie interpretů','Artist photographs')} (${photographers.length})</summary><ul data-no-translate>${photographers.map(item=>`<li><strong>${esc(item.name)}</strong> — ${credit(item)}</li>`).join('')}</ul></details>`:''}<p>${t('Festivalové ilustrace a případné typografické plakáty vznikly pro Prague Pulse Fest. Jména interpretů v navrženém programu neznamenají potvrzenou účast.','Festival illustrations and any typographic posters were created for Prague Pulse Fest. Artist names in the proposed programme do not imply confirmed attendance.')}</p><a href="images/PHOTO-CREDITS.md" class="text-button">${t('Úplný původ vizuálů','Complete artwork credits')}</a></section>`;
}
function info(){
main.innerHTML=crumb('Praktické informace')+heading('Prague Pulse Fest','Informace pro návštěvníky','Doprava, parkování, ubytování a vše důležité před návštěvou.')+`<nav class="info-jump" aria-label="Informace na stránce"><a href="#travel">Doprava</a><a href="#parking">Parkování</a><a href="#stay">Ubytování</a><a href="#contacts">Kontakt</a><a href="#privacy">Soukromí</a></nav><section class="grid three"><article class="card"><p class="eyebrow">Kdy</p><h2>1.–3. srpna 2027</h2><p>Program každý den od 09:00<br>3 dny · 3 scény · 60 účinkujících</p></article><article class="card"><p class="eyebrow">Kde</p><h2>Vltava Park</h2><address>${esc(D.festival.location.street)}<br>${esc(D.festival.location.postalCode)} Praha 7<br>Výstaviště Praha</address></article><article class="card" id="contacts"><p class="eyebrow">Kontakt</p><h2>Festivalové info</h2><p><a href="mailto:${esc(D.festival.contact.email)}">${esc(D.festival.contact.email)}</a></p><p>${esc(D.festival.contact.phone)}</p><p class="count">Kontaktní údaje patří fiktivnímu festivalu a nejsou určené pro skutečné objednávky.</p></article></section><section class="grid three"><article class="card" id="travel"><h2>Jak se k nám dostat</h2><p>Tramvají na Výstaviště nebo metrem C na Nádraží Holešovice. Z centra doporučujeme MHD, pěší cestu přes Stromovku nebo kolo.</p><a class="text-button" href="https://pid.cz/" target="_blank" rel="noopener noreferrer">Vyhledat spojení PID ↗</a></article><article class="card" id="parking"><h2>Parkování</h2><p>V okolí Výstaviště jsou placená parkoviště a městské parkovací zóny. Respektuj místní značení. VIP parkování je součástí modelového třídenního balíčku, ostatní vstupenky ho nezahrnují.</p></article><article class="card" id="stay"><h2>Ubytování</h2><p>Pro krátkou cestu do areálu vybírej Holešovice, Letnou nebo okolí metra C. Ubytování rezervuj přímo u poskytovatele. Festivalový balíček nezahrnuje hotel ani kemp.</p></article></section><aside id="accessibility" class="notice"><strong>Přístupnost areálu</strong><p>Bezbariérové trasy a přístupné toalety jsou součástí návrhu. Potřebuješ-li asistenci, obrať se na informační bod u vstupu.</p></aside><section id="map"><div class="section-head"><h2>Mapa areálu</h2><a class="text-button" href="https://www.google.com/maps/search/?api=1&query=V%C3%BDstavi%C5%A1t%C4%9B+67+Praha" target="_blank" rel="noopener noreferrer">Otevřít Google Maps ↗</a></div><div id="map-container" class="map-frame" aria-label="Mapa areálu"></div></section><section id="history" class="history-panel"><p class="eyebrow">Historie festivalu</p><h2>První ročník v Praze</h2><p>Prague Pulse Fest 2027 spojuje tři odlišné scény do jednoho městského festivalu. První ročník staví na současné hudbě, objevování nových jmen a pohodlné dostupnosti městskou dopravou.</p></section><section id="faq"><h2>Časté dotazy</h2>${infoItems.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</section><section id="privacy"><p class="eyebrow">Soukromí / GDPR</p><h2>Jak pracujeme s údaji</h2><p>Účet, košík, oblíbené a objednávky se ukládají do místního úložiště prohlížeče na tvém zařízení. Heslo se ukládá jako solený hash, nikoli jako čitelný text. Přihlášení je platné sedm dnů, pokud se neodhlásíš dříve.</p><p>Web nepoužívá analytické cookies a neposílá osobní údaje na náš server. Smazání dat prohlížeče odstraní i místní účty a objednávky.</p><p>Google Maps je externí služba. Po povolení externích map v nastavení soukromí se mapa načítá automaticky; bez souhlasu zůstává vypnutá. Sociální odkazy vedou na veřejné stránky jednotlivých platforem; nejde o ověřené profily tohoto fiktivního festivalu.</p><p>Tato stránka popisuje fungování školního klientského projektu, nikoli právní dokument skutečného pořadatele.</p></section><section id="terms"><p class="eyebrow">Podmínky</p><h2>Objednávka a vstupenky</h2><p>Festival i nabídka jsou fiktivní. Platba v košíku je zkušební a nestrhává peníze. Vytvořené PDF není dokladem o skutečném zaplacení nebo právu na vstup na existující akci. E-mail se automaticky neodesílá.</p><p>Obsazenost odpovídá objednávkám uloženým v daném prohlížeči. Není sdílená mezi zařízeními. Třídenní balíček blokuje stejné místo pro všechny tři dny; jednodenní pouze pro vybraný den.</p></section>`;
main.insertAdjacentHTML('beforeend',photoCreditsHtml());
window.PulsePrivacy.mountMap($('#map-container'));
const anchor=new URLSearchParams(location.search).get('section')||location.hash.slice(1);if(anchor&&/^[a-z]+$/.test(anchor))requestAnimationFrame(()=>document.getElementById(anchor)?.scrollIntoView());
}
function search(){main.innerHTML=crumb('Vyhledávání')+heading('Program, účinkující a informace','Vyhledávání','Prohledáváme všechny položky dat festivalu, program, účinkující, scény i praktické informace. Bez ohledu na velikost písmen a diakritiku.')+`<form class="filters" id="search-form" role="search"><div class="field"><label for="query">Hledat na celém webu</label><input id="query" name="q" type="search" maxlength="120" placeholder="Např. David, VIP nebo doprava" autocomplete="off"></div><button>Vyhledat →</button></form><p id="search-count" role="status" class="count"></p><div id="search-results"></div>`;
$('#query').value=new URLSearchParams(location.search).get('q')?.slice(0,120)||'';
const groups=[['Účinkující',D.performers,x=>`performers.html?id=${x.id}`],['Program',D.events,x=>`program.html?event=${x.id}`],['Scény',D.venues,x=>`venues.html#${x.id}`],['Dny festivalu',D.festival.dates,x=>`program.html?day=${x.id}`],['Vstupenky',ticketTypes.map(t=>({name:t.label,description:`${t.price} Kč · Jednodenní vstupenka`,...t})),()=> 'tickets.html'],['Festivalové balíčky',D.festival.tickets,()=> 'tickets.html'],['Festival',[D.festival],()=> 'index.html'],['Odkazy festivalu',D.festival.links,()=> 'info.html'],['Novinky',window.PulseNews?.searchItems?.(window.PulseI18n?.lang||'cs')||[],x=>`news.html?id=${encodeURIComponent(x.id)}`],['Praktické informace',infoItems.map(([name,description])=>({name,description})),()=> 'info.html']];
function render(){const q=normalize($('#query').value.trim());let total=0;$('#search-results').innerHTML=q?groups.map(([title,items,href])=>{const found=items.filter(x=>normalize(localizedSearch(x)).includes(q));total+=found.length;return found.length?`<section class="result-group"><h2>${title} <span class="count">(${found.length})</span></h2><div class="grid">${found.map(x=>`<article class="card"><span class="badge">${title}</span><h3>${link(href(x),esc(x.theme||x.name||x.title))}</h3><p class="muted">${esc(x.description||x.performers?.join(' · ')||x.location?.city||x.date||x.url||'Prague Pulse Fest')}</p>${link(href(x),'Zobrazit detail →','text-button')}</article>`).join('')}</div></section>`:'';}).join(''):'<div class="empty">Napiš alespoň jeden znak. Zkus třeba „David“ nebo „VIP“.</div>';$('#search-count').textContent=q?`${total} výsledků pro „${$('#query').value.trim()}“`:'';if(q&&!total)$('#search-results').innerHTML='<div class="empty">Nic jsme nenašli. Zkus kratší výraz nebo jiné slovo.</div>';}
$('#search-form').onsubmit=e=>{e.preventDefault();const searchUrl=new URL(location.href);searchUrl.searchParams.set('q',$('#query').value.trim());history.replaceState(null,'',searchUrl);render();};$('#query').oninput=render;render();}
const festivalDays=['d1','d2','d3'];
const festivalEdition=Number(D.festival.dates[0].date.slice(0,4));
function ticketFor(day,seat,scope='day'){
const category=seat.startsWith('S')?'standing':seat[0]<='B'?'vip':'regular',type=ticketTypes.find(t=>t.id===category);
return {day:scope==='festival'?'d1':day,seat,category,scope,days:scope==='festival'?[...festivalDays]:[day],price:scope==='festival'?type.festivalPrice:type.price};
}
function validTicket(t){if(!t||!/^d[123]$/.test(t.day)||!/^(?:[A-F][1-8]|S(?:[1-9]|[1-3][0-9]|40))$/.test(t.seat)||!['day','festival',undefined].includes(t.scope))return false;const expected=ticketFor(t.day,t.seat,t.scope||'day');return expected.price===t.price&&expected.category===t.category&&(!t.days||JSON.stringify(t.days)===JSON.stringify(expected.days));}
const ticketDays=t=>t.scope==='festival'?['d1','d2','d3']:[t.day];
const ticketKey=t=>`${t.scope==='festival'?'festival':t.day}:${t.seat}`;
const overlaps=(a,b)=>a.seat===b.seat&&ticketDays(a).some(day=>ticketDays(b).includes(day));
function occupied(day){const seats=new Set();for(const o of storage.get('orders'))if((o.edition??2026)===festivalEdition)for(const t of o.tickets||[])if(ticketDays(t).includes(day))seats.add(t.seat);return seats;}
function occupiedFor(day,scope){return new Set((scope==='festival'?festivalDays:[day]).flatMap(d=>[...occupied(d)]));}
const ticketLabel=t=>`${t.scope==='festival'?'3 dny · ':''}${ticketTypes.find(c=>c.id===t.category)?.label||''} · ${t.category==='standing'?'místo ke stání '+t.seat.slice(1):'sedadlo '+t.seat}`;
const ticketDate=(t,edition=festivalEdition)=>t.scope==='festival'?`1.–3. srpna ${edition}`:date(D.festival.dates.find(d=>d.id===t.day).date.replace(/^\d{4}/,String(edition)))+' '+edition;

const promoCatalog=Object.freeze({PULSE10:{percent:10},PRAHA200:{amount:200}});
const normalizePromo=value=>String(value||'').trim().toUpperCase();
function promoTotals(tickets,code=''){
const subtotal=tickets.reduce((sum,t)=>sum+ticketFor(t.day,t.seat,t.scope||'day').price,0),normalized=normalizePromo(code),promo=Object.hasOwn(promoCatalog,normalized)?promoCatalog[normalized]:null;
const discount=promo?Math.min(subtotal,promo.amount||Math.round(subtotal*promo.percent/100)):0;
return {subtotal,discount,total:subtotal-discount,promoCode:promo?normalizePromo(code):''};
}
function savedPromo(){try{const code=normalizePromo(JSON.parse(localStorage.getItem('pulse:promo:'+cartKey())||'null')?.code);return Object.hasOwn(promoCatalog,code)?code:'';}catch{return '';}}
const paymentMethods=Object.freeze({card:['Platební karta','Payment card'],banktransfer:['Bankovní převod','Bank transfer'],cash:['Hotově na pokladně','Cash at the box office'],applepay:['Apple Pay','Apple Pay'],googlepay:['Google Pay','Google Pay'],benefitplus:['Benefit Plus','Benefit Plus'],invoice:['Na fakturu','Invoice']});
const paymentAction=method=>({card:tr('Simulovat platbu kartou','Simulate card payment'),banktransfer:tr('Simulovat bankovní převod','Simulate bank transfer'),cash:tr('Simulovat platbu hotově','Simulate cash payment'),applepay:tr('Simulovat Apple Pay','Simulate Apple Pay'),googlepay:tr('Simulovat Google Pay','Simulate Google Pay'),benefitplus:tr('Simulovat Benefit Plus','Simulate Benefit Plus'),invoice:tr('Simulovat objednávku na fakturu','Simulate invoice order')})[method]||tr('Simulovat platbu','Simulate payment');
const phoneValid=value=>/^[+()\d\s.-]+$/.test(value)&&/^\d{9,15}$/.test(value.replace(/\D/g,''));

function tickets(){
const params=new URLSearchParams(location.search);let day=params.get('day');if(!festivalDays.includes(day))day='d1';
let scope=['festival','day'].includes(params.get('scope'))?params.get('scope'):params.has('day')?'day':'festival',category=ticketTypes.some(t=>t.id===params.get('category'))?params.get('category'):'all';
main.innerHTML=crumb('Vstupenky')+heading('Prague Pulse Fest / 2027','Vstupenky','Tři dny na všech scénách, nebo jen jeden festivalový den. Vyber balíček a konkrétní místo.')+`<section class="grid three package-grid" aria-label="Třídenní festivalové balíčky">${ticketTypes.map(type=>{const source=D.festival.tickets.find(t=>t.id===type.sourceId);return `<article class="card package-card"><span class="badge">1.–3. srpna / 3 dny</span><h2>${type.label}</h2><p class="package-price">${money(type.festivalPrice)}</p><p>${esc(source.description)}</p><button data-package-category="${type.id}" class="full">Vybrat ${type.label} →</button></article>`;}).join('')}</section><section id="quick-purchase" class="card quick-purchase" aria-labelledby="quick-heading"><p class="eyebrow">${tr('Rychlý nákup','Quick purchase')}</p><h2 id="quick-heading">${tr('Vstupenky pro tebe i celou partu','Tickets for you and your group')}</h2><p>${tr('Vyber kategorii a počet osob. Přidělíme ti volná místa; konkrétní sedadla můžeš vybrat také v mapě níže.','Choose a category and the number of people. We will assign available places; you can also choose specific seats in the map below.')}</p><form id="quick-ticket-form"><div class="quick-ticket-fields filters"><div class="field"><label for="quick-category">${tr('Kategorie','Category')}</label><select id="quick-category">${ticketTypes.map(t=>`<option value="${t.id}">${t.label}</option>`).join('')}</select></div><div class="field"><label for="quick-scope">${tr('Délka vstupu','Ticket duration')}</label><select id="quick-scope"><option value="festival">${tr('Celý festival · 3 dny','Full festival · 3 days')}</option><option value="day">${tr('Jeden den','One day')}</option></select></div><div class="field"><label for="quick-day">${tr('Festivalový den','Festival day')}</label><select id="quick-day">${D.festival.dates.map(d=>`<option value="${d.id}">${date(d.date)}</option>`).join('')}</select></div><div class="field"><label for="quick-quantity">${tr('Počet osob','Number of people')}</label><input id="quick-quantity" type="number" value="1" min="1" max="8" step="1" inputmode="numeric" required></div></div><p id="quick-summary" class="quick-summary" aria-live="polite"></p><p id="quick-error" class="error" role="alert"></p><button id="quick-buy" type="submit">${tr('Koupit a pokračovat','Buy and continue')} →</button></form></section><section id="ticket-selector"><div class="filters"><div class="field"><label for="ticket-scope">Délka vstupu</label><select id="ticket-scope"><option value="festival">Celý festival · 3 dny</option><option value="day">Jeden den</option></select></div><div class="field"><label for="ticket-day">Festivalový den</label><select id="ticket-day">${D.festival.dates.map(d=>`<option value="${d.id}">${date(d.date)} · ${esc(d.theme)}</option>`).join('')}</select></div><div class="field"><label for="ticket-category">Kategorie</label><select id="ticket-category"><option value="all">Všechny kategorie</option><option value="vip">VIP</option><option value="regular">Regular</option><option value="standing">Stání</option></select></div></div><div class="seat-layout"><section class="card"><h2>Výběr místa</h2><p id="scope-help" class="muted"></p><div class="stage">PÓDIUM</div><div id="seat-map" class="seat-map" role="group" aria-label="Výběr sedadel"></div><div class="legend"><span><i class="v"></i>VIP</span><span><i></i>Regular</span><span><i class="s"></i>Vybráno / v košíku</span><span><i class="o"></i>Obsazeno</span></div><button id="standing" class="standing secondary"></button><p class="count" id="standing-count"></p><p class="count">Vybrané místo zrušíš opětovným kliknutím. Místa v košíku odebereš v košíku.</p></section><aside class="card summary"><p class="eyebrow">Souhrn výběru</p><h2>Vybrané vstupenky</h2><div id="selection" aria-live="polite"></div><button id="add-cart" class="full">Přidat do košíku →</button><div class="actions">${link('cart.html','<svg class="cart-icon" aria-hidden="true" viewBox="0 0 24 24" fill="none"><path d="M3 3h2l2 12h11l3-9H6M9 20h.01M18 20h.01" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round"/></svg><span>Přejít do košíku</span>','button cart-go')}</div></aside></div></section>`;
$('#ticket-day').value=day;$('#ticket-scope').value=scope;$('#ticket-category').value=category;
$('#quick-day').value=day;$('#quick-scope').value=scope;$('#quick-category').value=category==='all'?'regular':category;
function availableQuick(){const quickDay=$('#quick-day').value,quickScope=$('#quick-scope').value,quickCategory=$('#quick-category').value,busy=occupiedFor(quickDay,quickScope),cart=getCart();const seats=quickCategory==='standing'?Array.from({length:40},(_,i)=>'S'+(i+1)):[...(quickCategory==='vip'?'AB':'CDEF')].flatMap(row=>Array.from({length:8},(_,i)=>row+(i+1)));return seats.filter(seat=>!busy.has(seat)&&!cart.some(t=>overlaps(t,ticketFor(quickDay,seat,quickScope))));}
function renderQuick(){const quickScope=$('#quick-scope').value,type=ticketTypes.find(t=>t.id===$('#quick-category').value),quantity=Number($('#quick-quantity').value),unitPrice=quickScope==='festival'?type.festivalPrice:type.price,available=availableQuick();$('#quick-day').disabled=quickScope==='festival';$('#quick-summary').textContent=`${tr('Cena za osobu','Price per person')}: ${money(unitPrice)} · ${tr('Volných míst','Available places')}: ${available.length}${Number.isInteger(quantity)&&quantity>=1&&quantity<=8?' · '+tr('Celkem','Total')+': '+money(unitPrice*quantity):''}`;$('#quick-buy').disabled=!available.length;}
$('#quick-ticket-form').oninput=()=>{$('#quick-error').textContent='';renderQuick();};
$('#quick-ticket-form').onsubmit=e=>{e.preventDefault();const quantity=Number($('#quick-quantity').value),error=$('#quick-error');error.textContent='';if(!Number.isInteger(quantity)||quantity<1||quantity>8){error.textContent=tr('Vyber počet osob od 1 do 8.','Choose between 1 and 8 people.');return;}const available=availableQuick();if(available.length<quantity){error.textContent=tr('V této kategorii není dost volných míst. Sniž počet osob nebo vyber jinou kategorii či den.','There are not enough places in this category. Reduce the number of people or choose another category or day.');renderQuick();return;}const items=available.slice(0,quantity).map(seat=>ticketFor($('#quick-day').value,seat,$('#quick-scope').value));if(save(cartKey(),[...getCart(),...items])){$('#quick-buy').disabled=true;selected.clear();location.href=routeUrl('cart.html');}};

function render(){
$('#ticket-day').disabled=scope==='festival';
$('#scope-help').textContent=scope==='festival'?'Stejné místo platí na všechny tři dny. Místo musí být volné po celý festival.':'Jednodenní vstup platí na všechny scény vybraného dne.';
const busy=occupiedFor(day,scope),cart=getCart(),cartSeats=new Set(cart.filter(t=>ticketDays(t).some(d=>(scope==='festival'?festivalDays:[day]).includes(d))).map(t=>t.seat));
for(const seat of selected)if(busy.has(seat)||cartSeats.has(seat))selected.delete(seat);
$('#seat-map').innerHTML=[...'ABCDEF'].map((row,i)=>{const rowCategory=i<2?'vip':'regular';if(category!=='all'&&category!==rowCategory)return '';const price=scope==='festival'?ticketTypes.find(t=>t.id===rowCategory).festivalPrice:ticketTypes.find(t=>t.id===rowCategory).price;return `<div class="row-label">ŘADA ${row} · ${i<2?'VIP':'REGULAR'} · ${money(price)}</div>`+Array.from({length:8},(_,j)=>{const seat=row+(j+1),taken=busy.has(seat),inCart=cartSeats.has(seat),sel=selected.has(seat);return `<button type="button" class="seat ${i<2?'vip':''} ${sel||inCart?'selected':''}" data-seat="${seat}" aria-pressed="${sel||inCart}" ${taken||inCart?'disabled':''} aria-label="${seat}, ${i<2?'VIP':'Regular'}, ${money(price)}, ${taken?'obsazeno':inCart?'v košíku':sel?'vybráno':'volné'}" title="${seat} · ${money(price)}">${taken?'×':seat}</button>`;}).join('');}).join('');
const free=Array.from({length:40},(_,i)=>'S'+(i+1)).filter(seat=>!busy.has(seat)&&!cartSeats.has(seat)&&!selected.has(seat));
$('#standing').hidden=!['all','standing'].includes(category);$('#standing').disabled=!free.length;$('#standing').textContent=`+ Přidat místo ke stání · ${money(scope==='festival'?ticketTypes[2].festivalPrice:ticketTypes[2].price)}`;
renderQuick();
$('#standing-count').hidden=$('#standing').hidden;$('#standing-count').textContent=`Stání: ${free.length} volných míst · vybráno ${[...selected].filter(seat=>seat.startsWith('S')).length}`;
const ts=[...selected].map(seat=>ticketFor(day,seat,scope));$('#selection').innerHTML=ts.length?ts.map(t=>`<div class="cart-item"><span>${esc(ticketLabel(t))}</span><button class="secondary small" data-unselect="${t.seat}" aria-label="Odebrat ${t.seat}">×</button></div>`).join('')+`<p class="total">${money(ts.reduce((sum,t)=>sum+t.price,0))}</p>`:'<p class="muted">Vyber sedadlo v mapě nebo přidej místo ke stání.</p>';$('#add-cart').disabled=!ts.length;
}
$('#ticket-day').onchange=()=>{day=$('#ticket-day').value;selected.clear();render();};$('#ticket-scope').onchange=()=>{scope=$('#ticket-scope').value;selected.clear();render();};$('#ticket-category').onchange=()=>{category=$('#ticket-category').value;render();};
main.querySelectorAll('[data-package-category]').forEach(button=>button.onclick=()=>{scope='festival';category=button.dataset.packageCategory;selected.clear();$('#ticket-scope').value=scope;$('#ticket-category').value=category;$('#quick-category').value=category;$('#quick-scope').value=scope;render();$('#ticket-selector').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});$('#ticket-category').focus({preventScroll:true});});
$('#seat-map').onclick=e=>{const seat=e.target.closest('[data-seat]')?.dataset.seat;if(seat){selected.has(seat)?selected.delete(seat):selected.add(seat);render();$('#seat-map').querySelector(`[data-seat="${seat}"]`)?.focus();}};
$('#selection').onclick=e=>{const seat=e.target.closest('[data-unselect]')?.dataset.unselect;if(seat){selected.delete(seat);render();($('#selection').querySelector('[data-unselect]')||$('#standing')).focus();}};
$('#standing').onclick=()=>{const busy=occupiedFor(day,scope),cart=getCart();const seat=Array.from({length:40},(_,i)=>'S'+(i+1)).find(seat=>!busy.has(seat)&&!selected.has(seat)&&!cart.some(t=>overlaps(t,ticketFor(day,seat,scope))));if(seat)selected.add(seat);render();};
$('#add-cart').onclick=()=>{const busy=occupiedFor(day,scope),cart=getCart();const ts=[...selected].filter(seat=>!busy.has(seat)&&!cart.some(t=>overlaps(t,ticketFor(day,seat,scope)))).map(seat=>ticketFor(day,seat,scope));if(save(cartKey(),[...cart,...ts])){selected.clear();render();updateCount();toast(`${ts.length} vstupenek přidáno do košíku.`);}};
window.addEventListener('storage',render);render();
}
function cart(draft={}){
const cart=getCart();main.innerHTML=crumb('Košík')+heading('Objednávka / 2027','Košík',tr('Zkontroluj vstupenky a doplň kontaktní údaje. Nakoupit můžeš s účtem i jako host.','Review your tickets and fill in your contact details. You can buy with an account or as a guest.'));
if(!cart.length){main.innerHTML+=`<section class="empty"><h2>Košík je prázdný</h2><p class="muted">${tr('Vyber kategorii, počet osob nebo konkrétní místa v mapě.','Choose a category, number of people or specific seats in the map.')}</p>${link('tickets.html',tr('Vybrat vstupenky →','Choose tickets →'),'button')}</section>`;return;}
const conflicts=cart.filter((t,i)=>ticketDays(t).some(day=>occupied(day).has(t.seat))||cart.slice(0,i).some(other=>overlaps(t,other)));
const accountParts=(user?.name||'').trim().split(/\s+/),firstName=draft.firstName??draft.name??accountParts.shift()??'',lastName=draft.lastName??accountParts.join(' ');
let activePromo=typeof draft.appliedPromo==='string'?draft.appliedPromo:savedPromo();if(!Object.hasOwn(promoCatalog,activePromo))activePromo='';
const inputPromo=draft.promoCode??activePromo;
main.innerHTML+=`<div class="seat-layout"><section class="card"><h2>Vybrané vstupenky</h2>${cart.map((t,i)=>`<article class="cart-item"><div><h3>${esc(ticketLabel(t))}</h3><p class="muted">${ticketDate(t)} · všechny scény</p><p>${money(t.price)} ${conflicts.includes(t)?'<strong class="danger">'+tr('· místo je obsazené nebo duplicitní, odeber ho','· this place is occupied or duplicated, remove it')+'</strong>':''}</p></div><button class="secondary small" data-remove="${i}" aria-label="${tr('Odebrat','Remove')} ${esc(ticketLabel(t))}">×</button></article>`).join('')}<p class="total">${tr('Cena vstupenek','Ticket subtotal')}: ${money(promoTotals(cart).subtotal)}</p>${link('tickets.html',tr('Upravit výběr / přidat vstupenky →','Edit selection / add tickets →'),'text-button')}</section><section class="card"><p class="eyebrow">Objednávka</p><h2>Dokončení objednávky</h2><p class="notice">${tr('Platba je simulovaná. Zvolená metoda neotevírá skutečnou platební službu ani nestrhává peníze. Po dokončení stáhneš PDF vstupenky; e-mail se automaticky neodesílá.','Payment is simulated. The selected method does not open a real payment service or charge money. Download your PDF tickets after completion; no email is sent automatically.')}</p>${user?`<p>${tr('Přihlášen jako','Signed in as')} <strong class="account-name">${esc(user.name)}</strong></p>`:`<p class="muted">Nakupuješ jako host. ${link('account.html?next=cart','Přihlásit se nebo registrovat →')}</p>`}<form id="checkout" class="form-stack"><div class="checkout-fields grid two"><div class="field"><label for="buyer-name">${tr('Jméno','First name')}</label><input id="buyer-name" name="firstName" required minlength="1" maxlength="80" autocomplete="given-name" value="${esc(firstName)}"></div><div class="field"><label for="buyer-surname">${tr('Příjmení','Last name')}</label><input id="buyer-surname" name="lastName" required minlength="1" maxlength="80" autocomplete="family-name" value="${esc(lastName)}"></div><div class="field"><label for="buyer-email">E-mail</label><input id="buyer-email" name="email" type="email" required maxlength="160" autocomplete="email" value="${esc(draft.email??user?.email??'')}" ${user?'readonly':''}></div><div class="field"><label for="buyer-phone">${tr('Telefon','Phone')}</label><input id="buyer-phone" name="phone" type="tel" required minlength="9" maxlength="30" autocomplete="tel" placeholder="+420 777 123 456" value="${esc(draft.phone||'')}"></div></div><div class="field promo-field"><label for="promo-code">${tr('Promo kód','Promo code')}</label><div class="actions"><input id="promo-code" name="promoCode" maxlength="32" autocomplete="off" value="${esc(inputPromo)}" aria-describedby="promo-message"><button id="apply-promo" type="button" class="secondary">${tr('Použít','Apply')}</button></div><p id="promo-message" class="count" role="status"></p></div><dl class="price-breakdown"><div class="price-row"><dt>${tr('Vstupenky','Tickets')}</dt><dd id="order-subtotal"></dd></div><div class="price-row" id="discount-row" hidden><dt>${tr('Sleva','Discount')} <span id="discount-code" data-no-translate></span></dt><dd id="order-discount"></dd></div><div class="price-row"><dt>${tr('Poplatky za objednávku','Booking fees')}</dt><dd>${money(0)}</dd></div><div class="price-row total"><dt>${tr('Celkem k úhradě','Total due')}</dt><dd id="order-total"></dd></div></dl><div class="field"><label for="payment-method">${tr('Způsob platby','Payment method')}</label><select id="payment-method" name="paymentMethod">${Object.entries(paymentMethods).map(([id,labels])=>`<option value="${id}">${tr(...labels)}</option>`).join('')}</select></div><div class="field"><label for="payment">Výsledek ukázkové platby</label><select id="payment"><option value="success">Simulovat úspěšnou platbu</option><option value="declined">Simulovat zamítnutí</option></select></div><label class="check"><input id="consent" type="checkbox" required><span>Souhlasím s <a href="info.html#terms">podmínkami objednávky</a> a beru na vědomí <a href="info.html#privacy">informace o zpracování údajů</a>.</span></label><p id="checkout-error" class="error" role="alert" tabindex="-1">${esc(draft.error||'')}</p><button id="checkout-submit" class="full" ${conflicts.length?'disabled':''}></button></form></section></div>`;
$('#consent').checked=Boolean(draft.consent);$('#payment').value=draft.payment||'success';$('#payment-method').value=Object.hasOwn(paymentMethods,draft.paymentMethod)?draft.paymentMethod:'card';
function formDraft(){return {firstName:$('#buyer-name').value,lastName:$('#buyer-surname').value,email:$('#buyer-email').value,phone:$('#buyer-phone').value,consent:$('#consent').checked,payment:$('#payment').value,paymentMethod:$('#payment-method').value,promoCode:$('#promo-code').value,appliedPromo:activePromo};}
function updateTotals(){const sums=promoTotals(cart,activePromo);$('#order-subtotal').textContent=money(sums.subtotal);$('#order-discount').textContent='−'+money(sums.discount);$('#order-total').textContent=money(sums.total);$('#discount-row').hidden=!sums.discount;$('#discount-code').textContent=sums.promoCode;$('#checkout-submit').textContent=`${paymentAction($('#payment-method').value)} · ${money(sums.total)} →`;}
function setPromo(code){if(!save('promo:'+cartKey(),{code}))return false;activePromo=code;updateTotals();return true;}
function applyPromo(){const code=normalizePromo($('#promo-code').value);if(code&&!Object.hasOwn(promoCatalog,code)){$('#promo-message').textContent=tr('Tento promo kód neplatí. Zkontroluj ho nebo pole vymaž.','This promo code is not valid. Check it or clear the field.');setPromo('');return;}if(setPromo(code)){$('#promo-code').value=code;$('#promo-message').textContent=code?tr('Promo kód byl uplatněn.','The promo code has been applied.'):tr('Promo kód byl odebrán.','The promo code has been removed.');}}
$('#apply-promo').onclick=applyPromo;$('#promo-code').oninput=()=>{if(normalizePromo($('#promo-code').value)!==activePromo){setPromo('');$('#promo-message').textContent=$('#promo-code').value?tr('Zadaný kód potvrď tlačítkem Použít.','Confirm the code using Apply.'):'';}};$('#promo-code').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();applyPromo();}};$('#payment-method').onchange=updateTotals;updateTotals();
if(activePromo)$('#promo-message').textContent=tr('Promo kód byl uplatněn.','The promo code has been applied.');
main.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{const state=formDraft(),items=getCart(),remove=cart[Number(b.dataset.remove)],updated=items.filter(t=>ticketKey(t)!==ticketKey(remove));if(save(cartKey(),updated)){updateCount();renderCart(state);}});
$('#checkout').onsubmit=e=>{e.preventDefault();const error=$('#checkout-error');error.textContent='';const firstName=$('#buyer-name').value.trim(),lastName=$('#buyer-surname').value.trim(),name=[firstName,lastName].join(' '),email=$('#buyer-email').value.trim().toLowerCase(),phone=$('#buyer-phone').value.trim(),method=$('#payment-method').value,code=normalizePromo($('#promo-code').value);
if(!firstName||!lastName||!emailValid(email)){error.textContent=tr('Zkontroluj jméno, příjmení a platný e-mail.','Check your first name, last name and email address.');return;}
if(!phoneValid(phone)){error.textContent=tr('Zadej platné telefonní číslo s 9 až 15 číslicemi.','Enter a valid phone number containing 9 to 15 digits.');$('#buyer-phone').focus();return;}
if(!Object.hasOwn(paymentMethods,method)){error.textContent=tr('Vyber způsob platby.','Choose a payment method.');return;}
if(code&&!Object.hasOwn(promoCatalog,code)){error.textContent=tr('Promo kód neplatí. Oprav ho nebo pole vymaž.','The promo code is not valid. Correct it or clear the field.');$('#promo-code').focus();return;}
if(code!==activePromo){error.textContent=tr('Před dokončením nejprve potvrď promo kód tlačítkem Použít.','Apply the promo code before completing your order.');$('#apply-promo').focus();return;}
if(!$('#consent').checked){error.textContent=tr('Pro pokračování potvrď podmínky objednávky.','Accept the order terms to continue.');return;}
if($('#payment').value==='declined'){error.textContent='Ukázková platba byla zamítnuta. Košík zůstává beze změny. Zkus úspěšnou simulaci.';return;}
const latest=getCart(),sameSelection=items=>JSON.stringify(items.map(t=>ticketKey(t)+':'+t.price).sort());
if(sameSelection(latest)!==sameSelection(cart)){renderCart({...formDraft(),error:tr('Košík se mezitím změnil v jiné kartě. Zkontroluj nový výběr a součet a objednávku potvrď znovu.','The cart changed in another tab. Review the new selection and total, then confirm your order again.')});updateCount();$('#checkout-error')?.focus();return;}
if(!latest.length||latest.some((t,i)=>ticketDays(t).some(day=>occupied(day).has(t.seat))||latest.slice(0,i).some(other=>overlaps(t,other)))){error.textContent=tr('Některé místo už není dostupné nebo je vybrané dvakrát. Odeber ho a vyber jiné.','A place is no longer available or has been selected twice. Remove it and choose another.');return;}
const totals=promoTotals(latest,code),order={id:'PP-'+keyId(),edition:festivalEdition,created:new Date().toISOString(),owner:user?.id||null,name,firstName,lastName,email,phone,paymentMethod:method,...totals,tickets:latest.map(t=>({...ticketFor(t.day,t.seat,t.scope||'day'),code:keyId()}))};
if(!save('orders',[...storage.get('orders'),order]))return;save(cartKey(),[]);save('promo:'+cartKey(),{code:''});updateCount();try{sessionStorage.setItem('pulse:last-order',order.id);}catch{}showOrder(order);};
}

const renderCart=cart;
function emailValid(s){return s.length<=160&&/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(s);}
async function download(o){
const buttons=[...main.querySelectorAll('[data-download]')].filter(b=>b.dataset.download===o.id);
buttons.forEach(b=>{b.disabled=true;b.setAttribute('aria-busy','true');});
try{await window.PulseTickets.download(o);toast('PDF vstupenky byly připraveny ke stažení.');}
catch(error){console.error('PDF generation failed',error);toast('PDF se nepodařilo vytvořit. Zkus to znovu.');}
finally{buttons.forEach(b=>{b.disabled=false;b.removeAttribute('aria-busy');});}
}
function orderHtml(o){return `<article class="order card"><p class="eyebrow">Dokončená objednávka</p><h2 class="order-id">Objednávka ${esc(o.id)}</h2><p data-no-translate>${esc(o.name)} · ${esc(o.email)}</p><p class="count">${new Date(o.created).toLocaleString(locale)}</p><div class="ticket-list">${o.tickets.map((t,i)=>`<div class="ticket-paper"><span class="badge">PRAGUE PULSE FEST</span><h3>${esc(ticketLabel(t))}</h3><p>${ticketDate(t,o.edition??2026)} · Vltava Park, Praha<br>${t.scope==='festival'?'Třídenní vstup':'Jednodenní vstup'} · všechny scény</p><p>${money(t.price)} · Kód: <span class="order-id">${esc(o.id)}-${i+1}</span></p></div>`).join('')}</div>${o.discount?`<dl class="price-breakdown"><div class="price-row"><dt>${tr('Cena vstupenek','Ticket subtotal')}</dt><dd>${money(o.subtotal)}</dd></div><div class="price-row"><dt>${tr('Sleva','Discount')} <span data-no-translate>${esc(o.promoCode)}</span></dt><dd>−${money(o.discount)}</dd></div></dl>`:''}<strong>${tr('Celkem','Order total')}: ${money(o.total)}</strong>${o.paymentMethod?`<p>${tr('Způsob platby','Payment method')}: ${esc(tr(...(Object.hasOwn(paymentMethods,o.paymentMethod)?paymentMethods[o.paymentMethod]:[o.paymentMethod,o.paymentMethod])))}</p>`:''}<div class="actions"><button data-download="${esc(o.id)}">Stáhnout PDF vstupenky ↓</button></div><p class="count">PDF obsahuje všechny vstupenky z této objednávky. Pro skutečný vstup na akci není platné.</p></article>`;}
function showOrder(o){main.innerHTML=crumb('Dokončená objednávka')+heading('Objednávka dokončena','Vstupenky ke stažení')+`<p class="notice">${o.owner?'Objednávku najdeš i v historii svého účtu.':'Vstupenky si stáhni a uschovej číslo objednávky.'}</p>`+orderHtml(o)+link('index.html','Zpět na festival →','text-button');main.focus();window.scrollTo(0,0);}
function bytesToHex(a){return [...new Uint8Array(a)].map(x=>x.toString(16).padStart(2,'0')).join('');}
async function passwordHash(password,salt){if(!crypto.subtle)throw new Error('Tento prohlížeč nepodporuje bezpečné zpracování hesla. Použij moderní prohlížeč.');const key=await crypto.subtle.importKey('raw',new TextEncoder().encode(password),'PBKDF2',false,['deriveBits']);return bytesToHex(await crypto.subtle.deriveBits({name:'PBKDF2',salt:new TextEncoder().encode(salt),iterations:120000,hash:'SHA-256'},key,256));}
function account(){if(user){const orders=storage.get('orders').filter(o=>o.owner===user.id);main.innerHTML=crumb('Můj účet')+heading('Přihlášený účet',`Můj účet`)+`<section class="card"><h2>Informace o účtu</h2><p class="account-name"><strong>${esc(user.name)}</strong><br>${esc(user.email)}</p><p class="muted">Přihlášení zůstává aktivní po dobu sedmi dnů nebo do odhlášení.</p><div class="actions"><button id="logout" class="secondary">Odhlásit se</button>${link('tickets.html','Vybrat další vstupenky →','button')}</div></section><section><h2>Historie objednávek <span class="count">(${orders.length})</span></h2>${orders.length?orders.slice().reverse().map(orderHtml).join(''):'<p class="empty">Zatím tu nejsou žádné objednávky.</p>'}</section>`;$('#logout').onclick=()=>{sessionStorage.removeItem('pulse:session');localStorage.removeItem('pulse:auth');user=null;location.href=routeUrl('account.html');};return;}
let mode='login';main.innerHTML=crumb('Můj účet')+`<div class="account-layout">${heading('Účet / Prague Pulse Fest','Přihlášení')}<section class="card"><div class="tabs" role="group" aria-label="Způsob přístupu"><button type="button" id="login-tab" aria-pressed="true">Přihlášení</button><button type="button" id="register-tab" class="secondary" aria-pressed="false">Registrace</button></div><form id="auth-form" class="form-stack"><div class="field hidden" id="name-field"><label for="auth-name">Jméno</label><input id="auth-name" autocomplete="name" minlength="2" maxlength="80"></div><div class="field"><label for="auth-email">E-mail</label><input id="auth-email" type="email" autocomplete="email" required maxlength="160" placeholder="jmeno@example.cz"></div><div class="field"><label for="auth-password">Heslo</label><input id="auth-password" type="password" required minlength="10" maxlength="128" autocomplete="current-password" aria-describedby="password-help"><small class="muted" id="password-help">10–128 znaků.</small></div><p class="error" id="auth-error" role="alert"></p><button id="auth-submit" class="full">Přihlásit se →</button></form></section></div>`;
function setMode(m){mode=m;$('#name-field').classList.toggle('hidden',m==='login');$('#auth-name').required=m==='register';$('#auth-password').autocomplete=m==='login'?'current-password':'new-password';$('#login-tab').setAttribute('aria-pressed',m==='login');$('#register-tab').setAttribute('aria-pressed',m==='register');$('#auth-submit').textContent=m==='login'?'Přihlásit se →':'Vytvořit účet →';$('#auth-error').textContent='';}
$('#login-tab').onclick=()=>setMode('login');$('#register-tab').onclick=()=>setMode('register');$('#auth-form').onsubmit=async e=>{e.preventDefault();const button=$('#auth-submit');button.disabled=true;$('#auth-error').textContent='';try{const email=$('#auth-email').value.trim().toLowerCase(),password=$('#auth-password').value,name=$('#auth-name').value.trim();if(!emailValid(email))throw new Error('Zadej platný e-mail.');if(password.length<10||password.length>128)throw new Error('Heslo musí mít 10 až 128 znaků.');const users=storage.get('users');let found=users.find(u=>u.email===email);if(mode==='register'){if(name.length<2)throw new Error('Jméno musí obsahovat alespoň dva znaky.');if(found)throw new Error('Tento e-mail už má účet. Přihlas se.');const salt=bytesToHex(crypto.getRandomValues(new Uint8Array(16)));found={id:keyId(),name,email,salt,hash:await passwordHash(password,salt)};if(!save('users',[...users,found]))return;}else{if(!found||await passwordHash(password,found.salt)!==found.hash)throw new Error('Nesprávný e-mail nebo heslo.');}
const guest=getCart(),guestPromo=savedPromo();rememberLogin(found.id);user=found;if(guest.length){const merged=[...getCart()];for(const t of guest)if(!merged.some(other=>overlaps(other,t)))merged.push(t);if(save(cartKey(),merged)){save('cart:guest',[]);if(guestPromo&&!savedPromo())save('promo:'+cartKey(),{code:guestPromo});save('promo:cart:guest',{code:''});}}location.href=routeUrl(new URLSearchParams(location.search).get('next')==='cart'?'cart.html':'account.html');}catch(err){$('#auth-error').textContent=err.message||'Přihlášení se nepodařilo.';}finally{button.disabled=false;}};}
main.addEventListener('click',e=>{const a=e.target.closest('[data-artist]');if(a)artistDetail(a.dataset.artist);const event=e.target.closest('[data-event]');if(event)eventDetail(event.dataset.event);const f=e.target.closest('[data-fav]');if(f){const fav=storage.get('favorites'),id=f.dataset.fav;const next=fav.includes(id)?fav.filter(x=>x!==id):[...fav,id];if(save('favorites',next)){f.setAttribute('aria-pressed',next.includes(id));f.textContent=next.includes(id)?'♥ Uloženo':'♡ Uložit';main.dispatchEvent(new Event('favorites-changed'));(main.querySelector(`[data-fav="${id}"]`)||$('#only-favorites'))?.focus();}}const dl=e.target.closest('[data-download]');if(dl){const o=storage.get('orders').find(x=>x.id===dl.dataset.download);if(o&&(o.owner===user?.id||(!o.owner&&o.id===sessionStorage.getItem('pulse:last-order'))))download(o);}});
shell();const routes={'index.html':home,'program.html':program,'performers.html':performers,'venues.html':venues,'info.html':info,'search.html':search,'tickets.html':tickets,'cart.html':renderCart,'account.html':account,'news.html':()=>window.PulseNews.render(main,new URLSearchParams(location.search).get('id'))};try{(routes[page]||home)();}catch(err){console.error(err);main.innerHTML=heading('Něco se nepodařilo','Zkus to prosím znovu.')+'<p>Pokud problém přetrvává, otevři web v aktuálním prohlížeči s povoleným místním úložištěm.</p>';}
})();
